export const makeVerbalSet = (seed) => {
  const r = rng(seed);
  return shuffleR(r, PASSAGES).slice(0, 3).flatMap((p, pi) =>
    p.statements.map(([s, right, why], si) => {
      const options = withKeys(["True", "False", "Cannot say"].map((label) => ({ label })));
      return { id: `w${pi}${si}`, section: "verbal", type: "text", passage: p, prompt: s, options, answer: options.find((o) => o.label === right).key, why };
    }),
  );
};

export const makeAbstractSet = (seed) => Array.from({ length: 10 }, (_, i) => ({
  id: `a${i}`,
  section: "abstract",
  prompt: "Which picture comes next in the sequence?",
  ...makeSequence(seed * 31 + i * 7),
}));

